const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Quebec boundary
  const quebec = ee.FeatureCollection('FAO/GAUL/2015/level1')
    .filter(ee.Filter.and(
      ee.Filter.eq('ADM0_NAME', 'Canada'),
      ee.Filter.eq('ADM1_NAME', 'Quebec')
    ))
    .geometry();

  // 2. Load MODIS Burned Area for 2023
  const burnedArea = ee.ImageCollection('MODIS/061/MCD64A1')
    .filterDate('2023-01-01', '2023-12-31')
    .filterBounds(quebec)
    .select('BurnDate');

  const collectionSize = burnedArea.size().getInfo();
  console.log(`Collection size: ${collectionSize} images`);

  if (collectionSize === 0) {
    console.log('No burned area data available for Quebec in 2023');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Create binary burn mask (any pixel that burned in 2023)
  const burned = burnedArea.map(function(img) {
    return img.gt(0);
  }).max(); // Maximum across all months creates binary burned/not-burned

  // 4. Calculate burned area
  // Each MODIS pixel is ~463m x 463m = ~21.4 hectares at equator
  // Use pixelArea() for accurate calculation
  const pixelArea = ee.Image.pixelArea().divide(10000); // Convert to hectares
  const burnedAreaImage = burned.multiply(pixelArea);

  // 5. Sum total burned area
  const stats = burnedAreaImage.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: quebec,
    scale: 500,
    maxPixels: 1e10
  });

  const totalBurnedHa = stats.get('BurnDate').getInfo();

  // 6. Count burned pixels for validation
  const pixelCount = burned.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: quebec,
    scale: 500,
    maxPixels: 1e10
  }).get('BurnDate').getInfo();

  console.log(`Burned pixels: ${pixelCount}`);
  console.log(`Total burned area: ${totalBurnedHa} hectares`);
  console.log(`Total burned area: ${(totalBurnedHa / 1000000).toFixed(2)} million hectares`);

  // 7. Validation and answer
  if (totalBurnedHa === null || totalBurnedHa === undefined || isNaN(totalBurnedHa)) {
    console.log('Calculation failed - invalid result');
    console.log('<answer>C3</answer>');
  } else if (pixelCount === 0) {
    console.log('No burned pixels detected in 2023');
    console.log('<answer>C2</answer>');
  } else if (totalBurnedHa >= 800000) {
    console.log('Burned area exceeds 0.8 million hectares');
    console.log('<answer>A</answer>');
  } else {
    console.log('Burned area is less than 0.8 million hectares');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
